data)]);$result['activated'][]=$provider;}$db->commit();return $result;
        }catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}finally{$db->query("SELECT RELEASE_LOCK('ipphp-whole-config-activation')");}
